44	/**
45	 * Global Exception handler for REST controllers.
46	 * <p>
47	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
48	 *
49	 * @author Vitaliy Fedoriv
50	 * @author Alexander Dudkin
51	 */
52	@ControllerAdvice
53	public class ExceptionControllerAdvice {
54	
55	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
56	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
57	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
58	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
59	
60	    private final OwnerFieldsValidator ownerFieldsValidator;
61	
62	    public ExceptionControllerAdvice(OwnerFieldsValidator ownerFieldsValidator) {
63	        this.ownerFieldsValidator = ownerFieldsValidator;
64	    }
65	
66	    /**
67	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
68	     * class.
69	     *
70	     * @param e     Object referring to the thrown exception.
71	     * @param status HTTP response status.
72	     * @param url URL request.
73	     */
74	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
75	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
76	        problemDetail.setType(URI.create(url.toString()));
77	        problemDetail.setTitle(e.getClass().getSimpleName());
78	        problemDetail.setDetail(detail);
79	        problemDetail.setProperty("timestamp", Instant.now());
80	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
81	        return problemDetail;
82	    }
83	
84	    /**
85	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
86	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
87	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
88	     * would catch it and report an authorization failure as a 500.
89	     *
90	     * @param e The {@link AccessDeniedException} to propagate
91	     * @throws AccessDeniedException always
92	     */
93	    @ExceptionHandler(AccessDeniedException.class)
94	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
95	        throw e;
96	    }
97	
98	    /**
99	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
100	     *
101	     * @param e The {@link Exception} to be handled
102	     * @param request {@link HttpServletRequest} object referring to the current request.
103	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
104	     */
105	    @ExceptionHandler(Exception.class)
106	    @ResponseBody
107	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
108	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
109	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
110	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
111	        return ResponseEntity.status(status).body(detail);
112	    }
113	
114	    /**
115	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
116	     * method returns a 404 Not Found status if an entity does not exist.
117	     *
118	     * @param e The {@link DataIntegrityViolationException} to be handled
119	     * @param request {@link HttpServletRequest} object referring to the current request.
120	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
121	     */
122	    @ExceptionHandler(DataIntegrityViolationException.class)
123	    @ResponseBody
124	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
125	        logger.warn("Data integrity violation at {} {}: {}",
126	            request.getMethod(),
127	            request.getRequestURI(),
128	            e.getMessage());
129	        logger.debug("Data integrity violation stacktrace", e);
130	        HttpStatus status = HttpStatus.NOT_FOUND;
131	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
132	        return ResponseEntity.status(status).body(detail);
133	    }
134	
135	    /**
136	     * Handles exception thrown by Bean Validation on controller methods parameters
137	     *
138	     * @param e The {@link MethodArgumentNotValidException} to be handled
139	     * @param request {@link HttpServletRequest} object referring to the current request.
140	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
141	     */
142	    @ExceptionHandler(MethodArgumentNotValidException.class)
143	    @ResponseBody
144	    public ResponseEntity<?> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
145	        HttpStatus status = HttpStatus.BAD_REQUEST;
146	        BindingErrorsResponse errors = new BindingErrorsResponse();
147	        BindingResult bindingResult = e.getBindingResult();
148	        if (bindingResult.getTarget() instanceof OwnerFieldsDto ownerFields) {
149	            List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFields);
150	            if (!missingFields.isEmpty()) {
151	                return ResponseEntity.status(status).body(new ValidationErrorsResponse(missingFields));
152	            }
153	        }
154	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
155	        if (bindingResult.hasErrors()) {
156	            errors.addAllErrors(bindingResult);
157	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
158	                .map(fieldError -> {
159	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
160	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
161	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
162	                        fieldError.getField(),
163	                        defaultMessage,
164	                        rejectedValue);
165	                    return new ValidationMessageDto(message)
166	                        .putAdditionalProperty("field", fieldError.getField())
167	                        .putAdditionalProperty("rejectedValue", rejectedValue)
168	                        .putAdditionalProperty("defaultMessage", defaultMessage);
169	                })
170	                .toList();
171	            logger.debug("Validation error at {} {}: {}",
172	                request.getMethod(),
173	                request.getRequestURI(),
174	                bindingResult.getFieldErrors());
175	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
176	            return ResponseEntity.status(status).body(detail);
177	        }
178	        return ResponseEntity.status(status).body(detail);
179	    }
