186	     * @param e The {@link MissingOwnerFieldsException} to be handled
187	     * @return A {@link ResponseEntity} containing the offending field names and a 400 Bad Request status.
188	     */
189	    @ExceptionHandler(MissingOwnerFieldsException.class)
190	    @ResponseBody
191	    public ResponseEntity<ValidationErrorsResponse> handleMissingOwnerFieldsException(MissingOwnerFieldsException e) {
